-- TORVO V2 secure Owner/Admin/Accountant Command Center metrics.
create or replace function public.get_dashboard_metrics() returns jsonb language plpgsql stable security definer set search_path=public as $$declare u app_users%rowtype;begin
 select * into u from app_users where auth_user_id=auth.uid() and active=true;
 if u.id is null or u.role not in('owner','admin','accountant') then raise exception 'STAFF ACCESS REQUIRED';end if;
 return jsonb_build_object('active_dealers',(select count(*) from dealers where status='approved'),'dealer_requests',(select count(*) from dealers where status<>'approved'),'sales_orders',(select count(*) from sales_documents where doc_type='sales_order' and status not in('cancelled','rejected')),'quotations',0,'estimates',(select count(*) from sales_documents where doc_type='estimate' and status not in('cancelled','rejected')),'low_stock',(select count(*) from inventory where current_qty<=reorder_level),'ready_dispatch',(select count(*) from dispatches where status='READY_FOR_DISPATCH'),'sale_approval_pending',(select count(*) from approval_requests where status='pending' and (module ilike '%sale%' or entity_type ilike '%sale%' or action_type ilike '%sale%')),'total_sales',(select coalesce(sum(s.estimate_total_snapshot),0) from marg_bill_sales s where s.status in('posted','approved')));end$$;
revoke all on function public.get_dashboard_metrics() from public,anon;grant execute on function public.get_dashboard_metrics() to authenticated;
